 afterTick(dt){this.separateEnemies(dt);if(this.mode!=='campaign'||!this.worldView)return;this.nameEnemies();this.feedback.tick();for(const [id,l]of this.interactLabels){const entry=this.worldView.objects.get(id),distance=entry.group.position.distanceTo(this.hero),done=this.zoneState.objects.includes(id);l.style.display=distance<10&&(!done||['waypoint','return','exit','boss','smith','supply','keeper','scout'].includes(entry.def.type))?'':'none';if(distance<10){const p=this.project(entry.group.position.clone().setY(1.0));l.style.transform=`translate(${p.x}px,${p.y}px) translate(-50%,-100%)`;}}this.worldView.tick?.(dt,this.hero,this.camera);this.onCampaignUi?.();this.drawMiniMap();if(this.uiRevision!==this.mapRevision){this.uiRevision=this.mapRevision;this.drawCampaign();}const nearest=[...this.worldView.objects.values()].filter(o=>o.group.position.distanceTo(this.hero)<1.8).sort((a,b)=>a.group.position.distanceTo(this.hero)-b.group.position.distanceTo(this.hero))[0];$('campaign-interact').textContent=nearest?'상호작용 · '+nearest.def.label:'상호작용 (E)';$('campaign-level').textContent='Lv.'+this.level+' · '+Math.floor(this.profileData.xp)+' / '+requiredXp(this.level)+' XP';$('campaign-location').textContent=this.region.name+(stratumCount(this)>1?' · '+stratumName(this)+' ['+(currentStratum(this)+1)+'/3]':'')+' · 권장 Lv.'+this.region.level+' · 난이도 '+this.profileData.tier;$('combat-score').textContent=this.kills+' 처치 · '+this.gold+' 금화 · '+this.profileData.ore+' 재료';$('combat-scene-title').textContent=this.region.name+(stratumCount(this)>1?' · '+stratumName(this):'');const percent=this.level>=MAX_LEVEL?100:Math.min(100,this.profileData.xp/requiredXp(this.level)*100),xp=$('combat-xp');xp.hidden=false;xp.setAttribute('aria-valuenow',percent.toFixed(1));xp.setAttribute('aria-valuetext','레벨 '+this.level+', '+percent.toFixed(1)+'퍼센트');$('combat-xp-fill').style.width=percent+'%';$('combat-xp-label').textContent=this.level>=MAX_LEVEL?'Lv.'+MAX_LEVEL+' · 최고 레벨':'Lv.'+this.level+' → '+(this.level+1)+' · '+Math.floor(this.profileData.xp)+' / '+requiredXp(this.level)+' XP';$('combat-xp-percent').textContent=percent.toFixed(1)+'%';for(const [id,type]of [['combat-heal','hp'],['combat-mana-potion','mana']]){const cd=Math.max(0,(this.potionCooldowns[type]||0)-this.time);$(id).textContent=(type==='hp'?'생명':'마나')+'약 '+this.profileData.potions[type]+(cd>0?' · '+Math.ceil(cd)+'초':'');$(id).disabled=cd>0||this.profileData.potions[type]<=0;$(id).title=type==='mana'?'최대 마나 35%를 4초 동안 회복 · 재사용 12초':'최대 생명 60% 회복 · 재사용 6초';}}
 drawMiniMap(){const c=$('campaign-minimap'),x=c.getContext('2d'),scale=c.width/SIZE,seen=new Set(this.zoneState.revealed),point=(wx,wz)=>{const [cx,cz]=worldCell(wx,wz);return[cx*scale,cz*scale];};x.fillStyle='#0c191e';x.fillRect(0,0,c.width,c.height);for(let z=0;z<SIZE;z++)for(let a=0;a<SIZE;a++){const k=z*SIZE+a;if(seen.has(k)&&this.map.tiles[k]){x.fillStyle='#596d52';x.fillRect(a*scale,z*scale,scale+.2,scale+.2);}}if(this.auto&&this.path.length){x.strokeStyle='#d6b36c';x.lineWidth=1;x.setLineDash([2,3]);x.beginPath();x.moveTo(...point(this.hero.x,this.hero.z));for(const p of this.path)x.lineTo(...point(p.x,p.z));x.stroke();x.setLineDash([]);}for(const o of this.map.objects){const [cx,cz]=worldCell(o.x,o.z);if(!seen.has(cz*SIZE+cx))continue;const px=cx*scale,pz=cz*scale,done=this.zoneState.objects.includes(o.id);x.fillStyle=o.type==='boss'?'#d39569':['portal','return','waypoint','exit'].includes(o.type)?'#8bc2c4':done?'#7c9b81':'#c8b075';x.beginPath();x.moveTo(px,pz-2.4);x.lineTo(px+2.4,pz);x.lineTo(px,pz+2.4);x.lineTo(px-2.4,pz);x.closePath();x.fill();}for(const m of this.monsters){if(m.dead)continue;const [cx,cz]=worldCell(m.actor.root.position.x,m.actor.root.position.z);if(!seen.has(cz*SIZE+cx))continue;x.fillStyle=m.boss?'#e3a267':'#c57f62';x.beginPath();x.arc(cx*scale,cz*scale,m.boss?2.5:1.25,0,Math.PI*2);x.fill();}const [hx,hz]=point(this.hero.x,this.hero.z);x.save();x.translate(hx,hz);x.rotate(-this.yaw);x.fillStyle='#f4ddb1';x.shadowColor='#f5c66d';x.shadowBlur=5;x.beginPath();x.moveTo(0,4);x.lineTo(-2.7,-2);x.lineTo(2.7,-2);x.closePath();x.fill();x.restore();x.fillStyle='#b5a581';x.font='10px Georgia,serif';x.textAlign='center';x.fillText('N',c.width/2,12);x.strokeStyle='#8d7751';x.lineWidth=1;x.strokeRect(4.5,4.5,c.width-9,c.height-9);}

 drawCampaign(){if(!this.profileData)return;this.setModeUi();$('campaign-regions').innerHTML=REGIONS.map(r=>`<button data-travel="${r.id}" ${this.profileData.unlocked.includes(r.id)?'':'disabled'} class="${this.region.id===r.id?'active':''}">${esc(r.name)}<small>Lv.${r.level}${this.profileData.completed.includes(r.id)?' · 완료':''}${this.profileData.waypoints.includes(r.id)?' · 경유지':''}</small></button>`).join('');const seals=this.map.objects.filter(o=>['seal','bell','rescue'].includes(o.type)),done=seals.filter(o=>this.zoneState.objects.includes(o.id)).length;$('campaign-quest').innerHTML='<strong>'+esc(this.region.name)+(stratumCount(this)>1?' · '+(currentStratum(this)+1)+'/3구간':'')+'</strong><p>'+esc(this.region.objective)+'</p>'+(seals.length?'<small>지역 목표 '+done+' / '+seals.length+' · 보스 '+(this.zoneState.boss?'완료':'미처치')+'</small>':'<small>장비를 준비하고 발견한 지역으로 출발하세요.</small>');this.drawInventory();}
