 upgrade(id){const item=this.item(id),p=this.profileData;if(this.region.id!=='camp'){this.log('강화는 야영지의 대장장이에게서 할 수 있습니다.');return;}if(!item||!p.inventory.includes(id))return;if((item.upgrade||0)>=5){this.log('최대 강화입니다.');return;}const cost=40*((item.upgrade||0)+1)**2,ore=(item.upgrade||0)+1;if(this.gold<cost||p.ore<ore){this.log('금화 '+cost+'와 강화 재료 '+ore+'개가 필요합니다.');return;}this.gold-=cost;p.ore-=ore;const seed=item.seed??Math.floor(this.map.random()*2147483647),next=rollItem(this.design,item.baseId||item.id,seed,(item.upgrade||0)+1);this.design.runtimeItems??=new Map();this.design.runtimeItems.set(next.id,next);p.instances.push({id:next.id,baseId:next.baseId,seed,upgrade:next.upgrade});p.inventory=p.inventory.map(x=>x===id?next.id:x);for(const slot of Object.keys(p.slots))if(p.slots[slot]===id)p.slots[slot]=next.id;this.binding=true;this.bridge.setLoadout(p.slots);this.binding=false;this.syncGear(null,true);this.mapRevision++;this.selectItem(next.id);audio.play('upgrade');this.log(next.name+' 강화 완료');this.persist();}
