 usePotion(type){if(this.mode!=='campaign'){super.usePotion(type);return false;}if(this.hp<=0||!['hp','mana'].includes(type))return false;const p=this.profileData;if(p.potions[type]<=0){this.log('야영지 보급관에게서 물약을 구입하세요.');return false;}if((this.potionCooldowns[type]||0)>this.time||type==='mana'&&this.manaPotion){this.log('물약 재사용 시간을 기다려 주세요.');return false;}if(this[type]>=this.stats[type]){this.log('이미 모두 회복했습니다.');return false;}p.potions[type]--;const policy=this.design.combatBalance||{};if(type==='mana'){const mp=policy.mana||{},duration=mp.potionDuration||4;this.manaPotion={until:this.time+duration,rate:this.stats.mana*(mp.potionFraction||.35)/duration};this.potionCooldowns.mana=this.time+(mp.potionCooldown||12);}else{this.hp=Math.min(this.stats.hp,this.hp+this.stats.hp*.6);this.potionCooldowns.hp=this.time+(policy.healthPotionCooldown||6);}audio.play('potion');this.effects.ring(type==='hp'?'fire':'ice',this.hero,.5,.4);this.persist();return true;}

